import java.util.*;
public class Pager {
  public static <T> List<T> page(List<T> rows, int page, int size) {
    if (page < 0 || size <= 0) throw new IllegalArgumentException();
    int from = page * size;
    return rows.subList(from, Math.min(from + size, rows.size()));
  }
}

