import java.util.*;
public class Pager {
  public static <T> List<T> page(List<T> rows, int page, int size) {
    if (page < 0 || size <= 0) throw new IllegalArgumentException();
    long from = (long) page * size;
    if (from >= rows.size()) return List.of();
    return new ArrayList<>(rows.subList((int) from, (int) Math.min(from + size, rows.size())));
  }
}

