    assert Pager.page(List.of(1,2,3), 2, 2).isEmpty();
    assert Pager.page(List.of(1), Integer.MAX_VALUE, 2).isEmpty();
    var rows = new ArrayList<>(List.of(1,2,3)); var page = Pager.page(rows,0,2); page.clear(); assert rows.size()==3;
    try { Pager.page(rows,-1,1); throw new AssertionError(); } catch (IllegalArgumentException expected) {}
    System.out.println("BehaviorCheck: PASS");
  }
}

